import React, { useLayoutEffect, useRef, useState } from 'react';
import Paper from '@material-ui/core/Paper';
import TableContainer from '@material-ui/core/TableContainer';
import LinearProgress from '@material-ui/core/LinearProgress';
import { useChainWheel } from 'utils/useContainWheel';

// The frame every list table sits in, so all tables behave the same: up to VISIBLE_ROWS rows show in full with the page scrolling as
// usual; only a longer list gets a fixed height of exactly VISIBLE_ROWS rows, and then just the rows scroll under a header that stays
// (the table is given stickyHeader). The height is measured from the real rows, so tall rows are counted as they are. The wheel over
// the rows scrolls the rows and, at their top or end, carries on with the page; the wheel anywhere else scrolls the page. The pager
// (footer) is outside the scrolling part, so it is always in view. refreshing = the rows are being read again: a thin bar on top.
export const VISIBLE_ROWS = 10;

// The height of a scrolling box that holds a table: undefined while it has VISIBLE_ROWS rows or fewer (it is not boxed in), else the
// measured height of its header and first VISIBLE_ROWS rows. Re-measured after every render and when the window is resized.
export const useTenRowsHeight = ref => {
  const [maxHeight, setMaxHeight] = useState(undefined);
  useLayoutEffect(() => {
    const measure = () => {
      const box = ref.current;
      if (!box) return;
      // a row that is one cell across the whole table is the hidden detail of the row before it (CollapseTable): it belongs to that
      // row, it is not one more row, so a list of expandable rows also shows VISIBLE_ROWS of them
      const rows = [...box.querySelectorAll('tbody tr')];
      const isDetail = row => row.children.length === 1 && row.children[0].hasAttribute('colspan');
      const dataRows = rows.filter(row => !isDetail(row));
      let next;
      if (dataRows.length > VISIBLE_ROWS) {
        const head = box.querySelector('thead');
        const end = rows.indexOf(dataRows[VISIBLE_ROWS]);
        next = Math.ceil(
          (head ? head.offsetHeight : 0) + rows.slice(0, end).reduce((sum, row) => sum + row.offsetHeight, 0)
        );
      }
      setMaxHeight(current => (current === next ? current : next));
    };
    measure();
    window.addEventListener('resize', measure);
    return () => window.removeEventListener('resize', measure);
  });
  return maxHeight;
};

const TableFrame = ({ children, footer, refreshing }) => {
  const ref = useRef(null);
  const maxHeight = useTenRowsHeight(ref);
  useChainWheel(ref);

  return (
    <Paper style={{ padding: 5 }}>
      {refreshing && <LinearProgress style={{ height: 2, borderRadius: 2 }} />}
      <TableContainer ref={ref} style={maxHeight ? { maxHeight } : undefined}>
        {children}
      </TableContainer>
      {footer}
    </Paper>
  );
};

export default TableFrame;
